  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-100) 0%,
    var(--dusk-50) 50%,
    var(--aurora-100) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--nordic-100) 50%,
    var(--aurora-100) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-550) 0%,
    var(--dusk-550) 50%,
    var(--dusk-300) 100%
  );

  /* Legacy semantic aliases mapped to latest token model */
  --card: var(--card-background);
  --card-foreground: var(--foreground);
  --popover: var(--popover-background);
  --popover-foreground: var(--foreground);
  --primary: var(--primary-background);
  --primary-hover: var(--primary-background-hover);
  --primary-foreground: var(--foreground-on-primary);
  --secondary: var(--secondary-background);
  --secondary-hover: var(--secondary-background-hover);
  --muted: var(--muted-background);
  --accent: var(--active-muted-background);
  --accent-foreground: var(--active-foreground);
  --mountain: var(--muted-background);
  --mountain-foreground: var(--foreground);
  --foreground-link: var(--link-foreground);
  --input: var(--border);
  --ring-shadow: var(--ring-muted);
  --ring-destructive: var(--ring-critical);
  --ring-destructive-shadow: var(--ring-critical-shadow);
  --backdrop: var(--overlay-background);
  --destructive: var(--destructive-background);
  --destructive-hover: var(--destructive-background-hover);
  --warning: var(--warning-background);
  --warning-hover: var(--warning-background-hover);
  --success: var(--success-background);
  --success-hover: var(--success-background-hover);
  --neutral: var(--neutral-background);
  --neutral-hover: var(--neutral-background-hover);
  --undefined: var(--neutral-muted-background);
  --undefined-hover: var(--neutral-background-hover);
  --undefined-foreground: var(--neutral-foreground);
  --disabled: var(--disabled-background);
  --hover: var(--background-hover);
  --destructive-foreground-alternate: var(--destructive-foreground-on-critical);
  --destructive-alternative: var(--destructive-muted-background);
  --warning-foreground-alternate: var(--warning-foreground-on-warning);
