  --inverted-destructive-foreground: var(--destructive-foreground);
  --inverted-success-foreground: var(--success-foreground);
  --decorative-background-mountain: var(--decorative-mountain-background);
  --decorative-background-fjord: var(--decorative-fjord-background);
  --decorative-background-nordic: var(--decorative-nordic-background);
  --decorative-background-aurora: var(--decorative-aurora-background);
  --decorative-background-dusk: var(--decorative-dusk-background);
  --decorative-background-orange: var(--decorative-orange-background);
  --decorative-background-sky: var(--decorative-sky-background);
  --decorative-background-gray: var(--decorative-mountain-background);
  --decorative-background-hover-mountain: var(--decorative-mountain-background-hover);
  --decorative-background-hover-fjord: var(--decorative-fjord-background-hover);
  --decorative-background-hover-nordic: var(--decorative-nordic-background);
  --decorative-background-hover-aurora: var(--decorative-aurora-background-hover);
  --decorative-background-hover-dusk: var(--decorative-dusk-background-hover);
  --decorative-background-hover-orange: var(--decorative-orange-background-hover);
  --decorative-background-hover-sky: var(--decorative-sky-background-hover);
  --decorative-background-hover-gray: var(--decorative-mountain-background-hover);
  --decorative-foreground-mountain: var(--decorative-mountain-foreground);
  --decorative-foreground-fjord: var(--decorative-fjord-foreground);
  --decorative-foreground-nordic: var(--decorative-nordic-foreground);
  --decorative-foreground-aurora: var(--decorative-aurora-foreground);
  --decorative-foreground-dusk: var(--decorative-dusk-foreground);
  --decorative-foreground-orange: var(--decorative-orange-foreground);
  --decorative-foreground-sky: var(--decorative-sky-foreground);
  --decorative-foreground-gray: var(--decorative-mountain-foreground);
  --sidebar: var(--mountain-900);
  --sidebar-foreground: var(--mountain-100);
  --sidebar-primary: var(--mountain-600);
  --sidebar-primary-foreground: var(--mountain-white);
  --sidebar-accent: var(--mountain-700);
  --sidebar-accent-foreground: var(--mountain-white);
  --sidebar-border: var(--mountain-800);
  --sidebar-ring: var(--gray-300);
}

.dark {
  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--nordic-600) 44%,
    var(--nordic-800) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-900) 0%,
    var(--aurora-600) 50%,
    var(--aurora-800) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-900) 0%,
    var(--dusk-600) 48%,
    var(--dusk-800) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-400) 0%,
    var(--dusk-700) 40%,
    var(--aurora-950) 60%,
    var(--aurora-900) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--dusk-950) 50%,
    var(--aurora-900) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-950) 0%,
    var(--nordic-900) 50%,
    var(--aurora-900) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-450) 0%,
    var(--dusk-450) 50%,
    var(--dusk-700) 100%
  );
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    @apply text-undefined-foreground;
  }
}

@layer utilities {
  [data-state="closed"] {
    --tw-animation-fill-mode: forwards;
  }

  @keyframes accordion-down {
    from {
      height: 0;
    }

    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }

    to {
      height: 0;
    }
  }

  .animate-accordion-down {
    animation: accordion-down 0.2s ease-out;
  }

  .animate-accordion-up {
    animation: accordion-up 0.2s ease-out;
  }
}
